ALTER TABLE public.culture_experiences ADD CONSTRAINT culture_a2e_mode_guard CHECK (a2e_kind IS NULL OR (a2e_kind='explore' AND play_mode='group' AND culture_layer IS NOT NULL AND trip_id IS NOT NULL AND days BETWEEN 2 AND 7) OR (a2e_kind='show' AND culture_layer IS NOT NULL AND days BETWEEN 2 AND 7 AND (play_mode='solo' OR trip_id IS NOT NULL)) OR (a2e_kind='inspire' AND culture_layer IS NULL AND (play_mode='solo' OR trip_id IS NOT NULL)));